-- Run this once in the Supabase SQL Editor (Project > SQL Editor > New query)

create table if not exists website_data (
  client_id text primary key,
  data jsonb not null,
  updated_at timestamptz not null default now()
);

alter table website_data enable row level security;
-- No policies added on purpose: only the service_role key (used server-side
-- by the Vercel function, never exposed to the browser) can read/write this
-- table. RLS with zero policies means the anon/public key gets nothing.

insert into website_data (client_id, data)
values ('framework-berlin', '{"_schema":"2.0","_updated":"2026-08-17","site":{"logo":"/brand_assets/Framework_White_Transparent.png","accent":"#1a3a2a","booking_url":"https://classpass.com/"},"home":{"hero":{"image":null,"headline":"High-Intensity.\nLow-Impact.\nAll Results.","sub":"Transform your body with Berlin''s premier Lagree training — science-backed, results-driven.","cta_text":"Book Your First Class"},"services":[{"title":"Group Lagree","desc":"High-intensity, low-impact full-body workouts on the Megaformer™. Perfect for building lean muscle, core strength, and endurance alongside a motivated community."},{"title":"Personal Training","desc":"One-on-one sessions tailored precisely to your fitness level and personal goals. Expert coaching for accelerated, lasting results on your schedule."},{"title":"Physiotherapy","desc":"Active physiotherapy for injury recovery and movement optimization. Qualified professionals provide personalized care to keep you moving freely and pain-free."}],"about":{"heading":"What is\nFramework?","body_1":"Framework is a boutique fitness studio offering a unique blend of Lagree™ training and active physiotherapy. Lagree is a highly intensive full-body muscle endurance workout performed on the Megaformer™ — a revolutionary machine designed to challenge every muscle group simultaneously.","body_2":"The method focuses on slow-twitch muscle fibers, building lean muscle mass and core strength while staying low-impact on your joints. You''ll feel the burn during — and for up to 24 hours after — every session."},"pricing":[{"credits":"2 Credits","name":"First Timer","amount":"€35","note":"€17.50 per class","popular":false},{"credits":"1 Credit","name":"Drop In","amount":"€35","note":"€35 per class","popular":false},{"credits":"5 Credits","name":"5 Classes","amount":"€160","note":"€32 per class","popular":false},{"credits":"10 Credits","name":"10 Classes","amount":"€290","note":"€29 per class","popular":true},{"credits":"20 Credits","name":"20 Classes","amount":"€520","note":"€26 per class","popular":false}],"locations":[{"neighborhood":"Prenzlauer Berg","name":"P-Berg Studio","address":"Christinenstraße 19a, 10119 Berlin","hours":"Mon – Thu: 8:00 am – 5:30 pm","image":"/framework-berlin/website/public/studio/pberg.png","img_position":"center 55%"},{"neighborhood":"Kreuzberg","name":"Kreuzberg Studio","address":"Oranienstraße 185, 10999 Berlin","hours":"Mon – Thu: 8:00 am – 5:30 pm","image":"/framework-berlin/website/public/studio/xberg.png","img_position":"center 38%"}],"testimonials":[{"quote":"The class was well-balanced with clear verbal cues and good flow. The instructor gave individual attention to each participant.","name":"Verified Class Review","badge":"ClassPass"},{"quote":"The instructor was welcoming and patient. The class was challenging but I never felt lost thanks to clear instructions.","name":"Verified Class Review","badge":"ClassPass"},{"quote":"A cozy, spa-like studio with high-quality Lagree equipment. Instructors are supportive and focused on safety and proper technique.","name":"Verified Class Review","badge":"ClassPass"},{"quote":"The Megaformer is genuinely intense — I was shaking after 20 minutes. The instructor kept the energy up and offered great modifications for my knee throughout.","name":"Verified Class Review","badge":"ClassPass"},{"quote":"Intimate studio, small class sizes, instructors who are genuinely invested. Feels premium but not intimidating. Already booked my next session.","name":"Verified Class Review","badge":"ClassPass"}],"cta":{"heading":"Ready to Transform\nYour Body?","sub":"Join our community of strong, empowered people across Berlin. Your first class is just one step away."}},"team":{"header":{"eyebrow":"Teacher-owned studio · Berlin","title":"The\nTeam","desc":"A collective of Lagree-certified instructors, physiotherapists, and movement specialists — here to push you, guide you, and celebrate every shake."},"philosophy":{"heading":"Teacher-owned.\nMovement-first.","body_1":"Framework Berlin was founded by teachers who believe the best fitness experience comes from instructors who practice what they teach. Every member of our team is trained to the highest standard in the Lagree method.","body_2":"We are a community of movement specialists dedicated to helping you achieve real, lasting results — safely, efficiently, and with care."},"members":[{"name":"Louise","role":"Instructor · Front of House","img":"public/team/louise.png","span":52,"d":0,"love":"there''s no better workout to achieve mind-muscle connection — and even though your body is working super hard, it feels meditative.","fact":"I''ve been living in Berlin for 10 years but I''m originally from tiny Luxembourg.","f3l":"Favourite exercise","f3":"Plank to pike & anything arms!"},{"name":"Diya","role":"Instructor","img":"public/team/diya.png","span":44,"d":1,"love":"it''s efficient — a cardiovascular and muscle-building workout in one, perfect for busy people and moms like me.","fact":"Just one? I was bitten by a lion.","f3l":"Favourite exercise","f3":"Any sort of Wheelbarrow × Cobra or Push-Up combo."},{"name":"Celia","role":"Instructor","img":"public/team/celia.jpg","span":36,"d":2,"love":"it''s helped me learn to embrace slowness and understand that less is often more. It gives me the best foundation of functional strength.","fact":"My last name is Morris & I was born in Morristown.","f3l":"Music style","f3":"Electronic pop with sprinkles of rock, country, hip hop, Arabic electronic, R&B, dub. Expect the unexpected."},{"name":"Juni","role":"Instructor · Physiotherapist","img":"public/team/juni.png","span":52,"d":3,"love":"it''s challenging, covers all important movement patterns in their multidimensional ways, and is my base for feeling strong and in control.","fact":"I''m afraid of ladybugs.","f3l":"Favourite exercise","f3":"The reverse giant kneeling crunch."},{"name":"Kika","role":"Instructor","img":"public/team/kika.jpg","span":44,"d":4,"love":"it pushes me to my limits and calms me down at the same time.","fact":"I am unbelievably clumsy and have a weakness for anything French.","f3l":"Music style","f3":"RnB, Psychedelic Pop, Afro House."},{"name":"Katta","role":"Instructor","img":"public/team/katta.png","span":36,"d":0,"love":"it keeps challenging and grounding me every time I step on the Mega — I love how it lets me \"leave reality\" and calms my very busy mind.","fact":"I''m in love with good food and veggies but I truly dislike capers and pickles.","f3l":"Favourite exercise","f3":"Former figure skater — I love the skater, but also in a love-hate relationship with the dancing bear."},{"name":"Lisanne","role":"Physiotherapist","img":"public/team/lisanne.png","span":52,"d":1,"love":"it helps me feel so connected to my body and what it''s capable of. I can push myself to my absolute limit without ever losing touch — psychically and mentally.","fact":"I have a habit of misplacing or losing all of my material possessions.","f3l":"Favourite exercise","f3":"One-sided wheelbarrow & any deep lunge variation."},{"name":"Shailan","role":"Instructor","img":"public/team/shailan.png","span":44,"d":2,"love":"it benefits my day-to-day life and makes me feel unstoppable.","fact":"Tell me everything about your dog. I am obsessed.","f3l":"Music style","f3":"Everything Beyoncé, Hip Hop, Funky House & R&B."},{"name":"Pauli","role":"Instructor","img":"public/team/pauli.jpg","span":36,"d":3,"love":"it pushes me to my mental and physical limits, zones me out and lets me forget the world for 50 minutes.","fact":"I can always tell you where to get the best coffee in town.","f3l":"Favourite exercise","f3":"Curtsy Lunge."},{"name":"Sarah","role":"Instructor","img":"public/team/sarah.png","span":52,"d":4,"love":"I love movement & progression.","fact":"I love Spaghetti Eis.","f3l":"Music style","f3":"Lo-Fi, all around 120bpm, 90s Hip Hop."},{"name":"Johanna","role":"Instructor","img":"public/team/johanna.png","span":44,"d":0,"love":"it makes me feel stronger — not only physically, but mentally. \"You can do everything for 20 seconds\" — Kika''s voice lives in my head rent free.","fact":"I have the memory of an elephant — tell me something once, I won''t forget it.","f3l":"Favourite exercise","f3":"Side torso crunch & I are in an exclusive relationship."},{"name":"Margot","role":"Instructor","img":"public/team/margot.png","span":52,"d":1,"love":"it is my mood booster — challenging my physical and mental limits one shake at a time.","fact":"I am fluent in four languages: Italian, French, German and English.","f3l":"Music style","f3":"Electro, Pop, Rock, Rap — I am eclectic."},{"name":"Anna","role":"Instructor","img":"public/team/anna.png","span":36,"d":2,"love":"it allows me to get out of my head like nothing else, while I can still be super present (and enjoy every shake).","fact":"Potatoes are my favourite veggie — so versatile!","f3l":"Favourite exercise","f3":"French Twist, or anything obliques really!"},{"name":"Sasha","role":"Instructor","img":"public/team/sasha.png","span":44,"d":3,"love":"it energizes and grounds me at the same time. The burn feeling leaves you wanting more each time.","fact":"My parents registered my birthday on Sep 25th instead of Oct 25th.","f3l":"Favourite exercise","f3":"Curtsy Lunge."},{"name":"Ben","role":"Instructor","img":"public/team/ben.png","span":52,"d":4,"love":"it''s brutal yet meditative — it trains your focus, self-talk and emotional control as much as your muscles. A constant negotiation with yourself.","fact":"I''m a Bravo expert — I excel at judging strangers'' life choices from the comfort of my couch.","f3l":"Music style","f3":"Techno in all forms — minimal, industrial, ambient. A perfect marriage for Lagree. A kind of \"sonic plank.\""},{"name":"Chele","role":"Instructor","img":"public/team/chele.png","span":52,"d":0,"love":"it connects body and mind like nothing else. It''s where I find clarity, resilience, and the kind of strength that shows up in every part of life.","fact":"I absolutely love being at the beach — but I cannot stand sand on my body or feet.","f3l":"Favourite exercise","f3":"Kneeling lat pulldown, or flying donkey kick when I''m feeling sassy."},{"name":"Nadeen","role":"Instructor","img":"public/team/nadeen.png","span":36,"d":1,"love":"not only is it a physical workout but a mental one. I feel challenged every time I walk in and accomplished every time I walk out.","fact":"I used to play soccer professionally for 10 years.","f3l":"Favourite exercise","f3":"The reverse giant soul train."},{"name":"Jackie","role":"Instructor","img":"public/team/jackie.png","span":44,"d":2,"love":"it never gets easy — even the tiniest adjustment can have you shaking like it''s your first class all over again!","fact":"I conquered my fear of deep water by learning to surf.","f3l":"Favourite exercise","f3":"Floor plank-to-pike & soul train."},{"name":"Lynn","role":"Instructor","img":"public/team/lynn.png","span":52,"d":3,"love":"it helps me become the strongest version of myself.","fact":"I have tons of cute dresses in my wardrobe but will walk around like Adam Sandler 90% of the time.","f3l":"Music style","f3":"Hip Hop, Deutschrap, R&B."},{"name":"Terry","role":"Instructor","img":"public/team/terry.png","span":36,"d":4,"love":"the mix of humility and strength I experience every time is humbling in the best way — I always leave feeling stronger and more accomplished.","fact":"A friend called me TerBear after Carebears in college — and that nickname somehow resurfaced in Berlin.","f3l":"Favourite exercise","f3":"All kinds of planks. In my head, if monsters attacked the earth, I''d need a plank. Everyone needs to plank for over a minute!"},{"name":"Chelsi","role":"Instructor","img":"public/team/chelsi.png","span":44,"d":0,"love":"I love the feeling of getting stronger physically and mentally, and how it quiets and calms my mind in a world that''s constantly overstimulating.","fact":"I''m from sunny Singapore but grew up in Bangkok — a tropical girlie always hunting for good Asian food in Berlin.","f3l":"Music style","f3":"Usually House / Techno / Trance — music is expression; it deeply follows the peaks and troughs in your life."},{"name":"Hannah","role":"Instructor","img":"public/team/hannah.png","span":52,"d":1,"love":null,"fact":null,"f3l":null,"f3":null},{"name":"Rachel","role":"Instructor","img":"public/team/rachel.png","span":36,"d":2,"love":"it''s tough, energizing, and leaves me feeling so strong. It''s my favourite way to train abs and engage the entire core.","fact":"I was super shy as a kid, but my dream before fitness was to become a singer.","f3l":"Favourite exercise","f3":"Catfish & Elevator Lunge."},{"name":"Cleo","role":"Instructor","img":"public/team/cleo.png","span":52,"d":3,"love":"it''s the most challenging and humbling workout I know — intense yet low impact, and it lets me fully tune into my body without distractions.","fact":"When I was 10, I played the saxophone in front of King Charles.","f3l":"Favourite exercise","f3":"Dancing bear & giant side torso crunch."},{"name":"Ella","role":"Instructor","img":"public/team/ella.png","span":44,"d":4,"love":"it''s the only workout that makes me feel strong, sculpted, and just the right amount of unstoppable. Slow-twitch muscles on fire? Yes please.","fact":"I believe in three things: good form, good vibes, and never trusting a plank that feels too easy.","f3l":"Favourite exercise","f3":"French Twist — nothing says snatched like obliques working overtime!"},{"name":"Dana","role":"Instructor","img":"public/team/dana.png","span":36,"d":0,"love":"it''s as much a mental challenge as a physical one. The slow pace strengthens my mind-muscle connection in a way that improves my day-to-day life.","fact":"I worked on electronics that are currently orbiting in space.","f3l":"Music style","f3":"A mix of everything — Afro house, pop, indie, bluegrass, Arabic. All of it."},{"name":"Lisa","role":"Instructor","img":"public/team/lisa.png","span":52,"d":1,"love":"it makes me my strongest and happiest self, inside out. I''ve never left a class without a smile on my face.","fact":"I could eat the same thing every single day without getting bored.","f3l":"Favourite exercise","f3":"Anything arms & obliques."},{"name":"Lara","role":"Instructor","img":"public/team/lara.png","span":44,"d":2,"love":"it proves, like nothing else, what you''re capable of when your body and mind work together as a team.","fact":"When I''m really focused or stressed, I just start singing out loud — whatever song is on my mind. I literally cannot hold it back.","f3l":"Favourite exercise","f3":"Express lunge, Cobra, and a good saw-to-inchworm combination."},{"name":"Suse","role":"Instructor","img":"public/team/suse.png","span":36,"d":3,"love":"it makes me stronger both mentally and physically and calms my mind. Those 50 minutes of class are my meditation.","fact":"I absolutely hate cooking.","f3l":"Music style","f3":"German Rap / Hip Hop, R''n''B — for workouts, anything with a beat that makes me wanna move."},{"name":"Tiff","role":"Instructor","img":"public/team/tiff.png","span":52,"d":4,"love":"it shows me a different way to be strong — not only does the workout ground me, it connects my mind and body, one slow-twitch muscle at a time.","fact":"I only have nature-themed tattoos — animals, flowers, insects. I like to think of myself as a zookeeper.","f3l":"Favourite exercise","f3":"I''m in a forever love-hate relationship with mega donkey kick and giant kneeling inner thighs."},{"name":"Victoria","role":"Instructor","img":"public/team/victoria.png","span":44,"d":0,"love":"it combines intensity and movement in a way that challenges my body while delivering immediate results. I was instantly hooked!","fact":"I have a habit of starting new hobbies and not finishing them.","f3l":"Favourite exercise","f3":"The bear in any variation!"},{"name":"Sofia","role":"Instructor","img":"public/team/sofia.png","span":36,"d":1,"love":"it''s the perfect full-body workout — bringing you to muscle failure while strengthening joints and increasing mental resilience.","fact":"I''m a huge Cape Town and hiking lover — Lion''s Head is my favourite morning workout and I''ve climbed it over 100 times.","f3l":"Favourite exercise","f3":"Bear in all variations — perfect form means every single muscle is engaged."}]},"physio":{"hero":{"image":null,"eyebrow":"Personalized care","title":"PT & Physiotherapy","desc":"Move better. Feel better. Perform better. Evidence-based physiotherapy tailored to your body, your goals, and your life.","cta_text":"Book a Session →","cta_url":"mailto:hello@frameworkberlin.com"},"intro":{"label":"Our approach","heading":"Root cause over symptom relief","body_1":"Are you dealing with pain, restrictions, or simply looking to improve your fitness and mobility? At Framework, we offer <strong>personalized sessions</strong> led by our experienced physiotherapists.","body_2":"With a <strong>comprehensive medical assessment</strong>, our goal is to identify the root cause of your issues rather than simply treating the symptoms. We combine manual therapy, movement re-education, and exercise prescription tailored specifically to your needs.","body_3":"Whether you''re recovering from an injury, managing a chronic condition, or optimizing performance — we work with you at every stage."},"services":[{"title":"Medical Assessment","text":"A thorough initial evaluation to understand your history, movement patterns, and underlying causes — not just your current complaint.","icon":"clipboard"},{"title":"Manual Therapy","text":"Hands-on treatment to restore mobility, reduce pain, and improve tissue health — tailored to your specific needs.","icon":"hand"},{"title":"Movement Re-Education","text":"Correcting faulty movement patterns that cause pain or inefficiency, and building lasting new habits through guided exercise.","icon":"arrow"},{"title":"Injury Rehabilitation","text":"Structured recovery programs following surgery, sports injuries, or accidents — from acute care through return to full activity.","icon":"rehab"},{"title":"Pregnancy & Postnatal Care","text":"Specialized treatment for women during and post pregnancy — safe, evidence-based support for every stage of the journey.","icon":"prenatal"},{"title":"Performance Optimization","text":"For athletes and active individuals seeking to train smarter, prevent injury, and reach their peak potential safely.","icon":"bolt"}],"specialists":[{"name":"Lisanne","title":"Physiotherapist","img":"public/team/lisanne.png","bio":["Lisanne brings over 6 years of clinical experience to Framework Berlin. She holds a B.Sc. in International Physiotherapy from the Netherlands and has worked in high-performance sports environments and chronic pain clinics.","Her practice is evidence-based and patient-centred — she takes the time to understand your full picture before designing a treatment plan that addresses the root cause, not just the symptoms."],"tags":["6+ years experience","B.Sc. International Physio","High-performance sports","Chronic pain"]},{"name":"Juni","title":"Physiotherapist · Lagree Instructor","img":"public/team/juni.png","bio":["Juni is both a qualified physiotherapist and a certified Lagree instructor, giving her an integrated perspective on movement and rehabilitation that few practitioners can offer.","She specializes in treatment for women <strong>during and post pregnancy</strong>, guiding clients safely through every stage with evidence-based care and genuine empathy."],"tags":["Lagree certified","Prenatal care","Postnatal rehab","Women''s health"]},{"name":"Margot","title":"Lagree Instructor · Level 1 Certified","img":"public/team/margot.png","bio":["Half-French, half-Italian and based in Berlin since 2019, Margot brings a distinctly European energy to every class. Her movement background spans multiple disciplines and her teaching style is both precise and encouraging.","You''ll find Margot on the reformer on <strong>weekend mornings at both studios</strong> — the ideal way to start your week."],"tags":["Level 1 Lagree","Weekend mornings","Both studios","Berlin since 2019"]},{"name":"Celia","title":"Lagree Instructor · Level 2 Certified","img":"public/team/celia.jpg","bio":["With a background in dance, Celia brings a sharp eye for alignment and body mechanics to everything she teaches. Two years into Lagree, she''s built a reputation for classes that challenge without compromising form.","Her focus on <strong>functional strength and alignment</strong> makes her sessions ideal for clients who want to move well, not just train hard."],"tags":["Level 2 Lagree","Dance background","Functional strength","Alignment specialist"]}],"process":{"label":"How it works","heading":"From first session to full recovery","steps":[{"title":"Initial Assessment","text":"Comprehensive evaluation of your history, movement patterns, and goals. We map the full picture before suggesting anything."},{"title":"Treatment Plan","text":"A personalized plan targeting the root cause — combining manual therapy, exercise prescription, and lifestyle guidance."},{"title":"Hands-On Sessions","text":"Focused 1:1 sessions in our studio, integrating treatment with movement re-education and progressive loading."},{"title":"Ongoing Support","text":"Regular reassessment and plan adjustments to keep you progressing — all the way to your goal and beyond."}]},"cta":{"heading":"Ready to start?","sub":"Book a consultation with Lisanne or Juni, or join Margot or Celia on the reformer — take the first step towards moving better.","btn_text":"Get in touch →","btn_url":"mailto:hello@frameworkberlin.com"}},"footer":{"tagline":"Premium Lagree & Physiotherapy Studio in Berlin","copyright":"© 2026 Framework Berlin. All rights reserved."}}'::jsonb)
on conflict (client_id) do update set data = excluded.data, updated_at = now();
